css:
header{position:absolute; top:0; right:0; display:flex; background:#fff;
  border-radius:0 0 0 24px; overflow:hidden}
header .cta{background:#F28100; border-radius:0; padding:0 24px}
.menu-btn{position:absolute; top:0; right:0; width:56px; height:44px; background:#111}
.scroll{position:absolute; right:8px; bottom:70px; writing-mode:vertical-rl;
  font-size:9px; letter-spacing:.2em}
.sidetab{position:fixed; right:0; writing-mode:vertical-rl; border-radius:12px 0 0 12px;
  padding:16px 10px; color:#fff; font-size:13px; letter-spacing:.06em}
.sidetab.a{top:28%; background:#4caf50} .sidetab.b{top:52%; background:#f4511e}
